#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

typedef long long ll;

int main() {
    int n;
    while (scanf("%d", &n), n) {
        ll l = 1, u = n * 10LL;
        ll m;
        while (l < u) {
            m = (l + u) / 2;
            int t[10] = {0}, d;
            ll newRoomNo = m;
            for (d = 0; newRoomNo; ++d, newRoomNo /= 10)
                t[d] = newRoomNo % 10;

            for (int i = d - 1; i > 0; --i) {
                if (t[i] == 4 || t[i] == 6) {
                    --t[i];
                    fill(t, t + i, 9);
                    break;
                }
            }

            ll res = 0;
            for (int i = 0; i < d; ++i) {
                ll a = 1;
                for (int j = 0; j < 3 * i; ++j) a *= 2;  // Replacing bit shift with multiplication
                res += (t[i] - (t[i] >= 6 ? 2 : t[i] >= 4 ? 1 : 0)) * a;
            }

            if (res < n)
                l = m + 1;
            else
                u = m;
        }
        printf("%lld\n", l);
    }
    return 0;
}

